// This adaptor exposes no API operations yet: prepare records on state
// so a later step can send them to Punto Solidario.
fn(state => {
  state.beneficiarios = state.data.hogares.map(h => ({
    cedula: h.cedula.replace(/-/g, ''), // national ID, digits only
    nombres: h.nombres,
    apellidos: h.apellidos,
    sexo: h.sexo,
    fechaNacimiento: h.fechaNacimiento, // YYYY-MM-DD
    provincia: h.provincia,
    municipio: h.municipio,
  }));
  return state;
});
